                    ['q' => "Une entreprise forme chaque ouvrier pour 1 200 MAD ; la production de chacun augmente ensuite de 300 MAD par mois. Au bout de combien de mois la formation est-elle rentabilisée ?", 'c' => ["3 mois", "4 mois", "6 mois", "12 mois"], 'a' => 1, 'e' => "1 200 ÷ 300 = 4 : le gain cumulé égale le coût au bout de 4 mois. Ensuite, la formation rapporte un bénéfice net."],
                    ['q' => "Pourquoi une entreprise hésite-t-elle à financer une formation générale, utile chez tous les employeurs ?", 'c' => ["Le salarié formé peut aller travailler ailleurs", "Elle fait baisser la productivité pendant plusieurs années", "La loi interdit de former des salariés en poste", "Elle coûte moins cher que l’embauche d’une personne déjà formée"], 'a' => 0, 'e' => "L’entreprise supporte le coût mais le bénéfice peut lui échapper si le salarié part. Elle finance plus volontiers des formations propres à son organisation."],
                    ['q' => "Quel est l’intrus dans cette liste ?", 'c' => ["Un tracteur agricole", "Une machine à coudre industrielle", "Un diplôme en comptabilité", "Un entrepôt frigorifique"], 'a' => 2, 'e' => "Le diplôme est incorporé à la personne : c’est du capital humain. Tracteur, machine et entrepôt sont des biens matériels, donc du capital physique."],
                    ['q' => "On observe que les diplômés gagnent plus que les non-diplômés. Quelle interprétation est la plus prudente ?", 'c' => ["Le diplôme explique à lui seul l’écart observé", "Le salaire détermine le diplôme obtenu", "Les écarts viennent de la taille de l’entreprise", "Les diplômés ne sont pas forcément comparables"], 'a' => 3, 'e' => "Corrélation n’est pas causalité : ceux qui font des études peuvent différer (aptitudes, milieu familial) avant même le diplôme."],
                ],
