            [
                'title' => "Participation, choix professionnel et mobilité",
                'description' => "Pourquoi on choisit de travailler, de changer de métier ou de région, et ce qui freine ces choix.",
                'questions' => [
                    ['q' => "Quand on choisit de travailler une heure de plus plutôt que de se reposer, quelle notion désigne ce à quoi on renonce ?", 'c' => ["Le coût fixe de production", "Le coût moyen par heure", "Le coût d’opportunité", "Le coût historique d’achat"], 'a' => 2, 'e' => "Choisir une option, c’est renoncer à la meilleure autre : l’heure de loisir perdue est le coût d’opportunité de l’heure travaillée."],
                    ['q' => "Une mère de deux enfants envisage de reprendre un emploi. Quel élément rend sa participation plus probable ?", 'c' => ["Une hausse du revenu de son conjoint", "Une crèche abordable à proximité", "Un allongement de son trajet quotidien", "Une baisse du salaire proposé"], 'a' => 1, 'e' => "Un mode de garde accessible réduit le coût de la reprise d’emploi. Les trois autres éléments jouent plutôt en sens inverse."],
                    ['q' => "Quand le salaire horaire augmente, l’effet de substitution pousse à :", 'c' => ["travailler plus, car le loisir coûte cher", "travailler moins, car on est plus riche", "se former moins longtemps", "accepter un poste plus éloigné"], 'a' => 0, 'e' => "Chaque heure de loisir fait perdre un salaire plus élevé : on remplace du loisir par du travail. L’effet de revenu, lui, peut agir en sens inverse."],
                    ['q' => "Un ouvrier gagne 40 MAD de l’heure et passe de 40 à 45 heures par semaine, sans majoration. Quel est son gain hebdomadaire supplémentaire ?", 'c' => ["40 MAD", "180 MAD", "1 800 MAD", "200 MAD"], 'a' => 3, 'e' => "5 heures de plus × 40 MAD = 200 MAD. Le chiffre de 1 800 correspond au salaire total à 45 heures, pas au supplément."],
                    ['q' => "Selon le modèle simple de migration, un ménage déménage si :", 'c' => ["les salaires sont identiques à l’arrivée", "le gain attendu dépasse le coût du départ", "le coût du départ dépasse le gain attendu", "la région d’arrivée est la plus proche de chez lui"], 'a' => 1, 'e' => "On compare l’avantage espéré (salaire, chances d’emploi) au coût (transport, logement, séparation) : un solde positif motive le départ."],
                    ['q' => "Un menuisier devient plombier après six mois de formation. Il illustre une mobilité :", 'c' => ["géographique, entre deux villes", "démographique", "professionnelle", "internationale"], 'a' => 2, 'e' => "Il change de métier, pas de lieu : c’est de la mobilité professionnelle. La mobilité géographique suppose un changement de région ou de ville."],
                    ['q' => "Qu’est-ce que le salaire de réservation ?", 'c' => ["Le salaire en dessous duquel on refuse un poste", "Le salaire garanti par la loi à tous", "Le salaire moyen de la profession", "Le salaire versé pendant un congé"], 'a' => 0, 'e' => "C’est le seuil personnel : sous ce niveau, on préfère continuer à chercher ou rester inactif. Il dépend des ressources, des charges et des alternatives."],
                    ['q' => "Quelle situation est un temps partiel subi ?", 'c' => ["Un étudiant qui choisit 15 heures pour réviser", "Une retraitée qui travaille 10 heures par plaisir", "Une indépendante qui fixe elle-même ses horaires", "Un caissier à 20 heures qui en voudrait 35"], 'a' => 3, 'e' => "Le temps partiel est subi quand le salarié souhaiterait travailler davantage mais l’employeur ne l’offre pas : c’est une forme de sous-emploi."],
                    ['q' => "Une usine ferme dans une ville sans autre grand employeur. Quel frein limite la mobilité des ouvriers vers d’autres régions ?", 'c' => ["Les frais de déménagement et les attaches familiales", "Un trop grand nombre d’offres dans la ville", "L’absence de besoin d’un salaire", "La baisse du prix des logements ailleurs"], 'a' => 0, 'e' => "Déménager coûte de l’argent et éloigne de la famille et du réseau social : ces coûts réduisent la mobilité même quand les salaires sont meilleurs ailleurs."],
                    ['q' => "Le chômage est élevé dans la région A alors que la région B a beaucoup de postes vacants. Quelle mesure peut aider ?", 'c' => ["Augmenter les droits de douane dans A", "Aider les chômeurs à déménager vers B", "Taxer les offres d’emploi de B", "Réduire les formations proposées dans A"], 'a' => 1, 'e' => "Le problème est un décalage géographique : réduire les coûts de mobilité (logement, transport, information) rapproche chômeurs et postes."],
                ],
            ],
            [
                'title' => "Différences salariales et structure des emplois",
                'description' => "Comprendre pourquoi les salaires diffèrent entre métiers, entreprises et groupes de travailleurs.",
                'questions' => [
                    ['q' => "Quel est le principe des différences compensatrices de salaire ?", 'c' => ["Les salaires baissent quand le travail est risqué", "Chaque emploi paie la même somme quelle que soit sa pénibilité", "Les écarts de salaire viennent de la durée des études", "Les emplois pénibles ou dangereux paient plus"], 'a' => 3, 'e' => "Pour attirer des travailleurs vers un poste pénible, dangereux ou de nuit, l’employeur doit offrir une prime : le salaire compense l’inconvénient."],
                    ['q' => "Pourquoi un ouvrier qui travaille sur échafaudage peut-il être payé plus qu’un ouvrier d’atelier, à qualification égale ?", 'c' => ["Le risque d’accident exige une compensation", "Il travaille moins d’heures par semaine", "Son métier est apparu plus récemment", "Son employeur a davantage de clients"], 'a' => 0, 'e' => "Le risque est un désagrément que le marché compense par une prime ; sans elle, peu de candidats accepteraient le poste."],
                    ['q' => "Dans une même entreprise, à poste et ancienneté égaux, une femme est payée 10 % de moins qu’un homme sans raison liée au travail. Cela relève de :", 'c' => ["la différence compensatrice", "l’effet de substitution entre travail et loisir", "la discrimination salariale", "le salaire d’efficience"], 'a' => 2, 'e' => "Un écart que ni la productivité ni les conditions de travail n’expliquent est de la discrimination. Les différences compensatrices reposent sur la pénibilité."],
                    ['q' => "Le salaire d’efficience repose sur l’idée qu’un salaire supérieur à celui du marché peut :", 'c' => ["faire baisser à coup sûr les coûts de production", "stimuler l’effort et retenir les salariés", "supprimer la concurrence entre entreprises", "rendre le contrôle de la qualité inutile"], 'a' => 1, 'e' => "Un employeur qui paie au-dessus du marché freine les démissions et l’absentéisme : le surcoût peut être compensé par la productivité. L’effet n’est pas garanti."],
                    ['q' => "Dans un marché du travail segmenté, on distingue :", 'c' => ["des emplois situés en ville et des emplois situés à la campagne", "des salaires nominaux et des salaires réels", "des actifs occupés et des actifs inoccupés", "un segment stable bien payé et un segment précaire"], 'a' => 3, 'e' => "La segmentation sépare un segment stable (bons salaires, protection) d’un segment précaire (bas salaires, contrats courts), avec peu de passage de l’un à l’autre."],
                    ['q' => "Un titulaire de master gagne 9 000 MAD par mois, un titulaire du bac 6 000 MAD. De combien le premier gagne-t-il de plus, en pourcentage ?", 'c' => ["33 %", "150 %", "50 %", "3 000 %"], 'a' => 2, 'e' => "(9 000 − 6 000) ÷ 6 000 = 0,5, soit +50 %. On rapporte l’écart au salaire de référence, ici 6 000 ; l’inverse donnerait 33 %."],
                    ['q' => "Dans une ville, le salaire moyen est de 6 000 MAD et le salaire médian de 4 500 MAD. Que suggère cet écart ?", 'c' => ["Quelques très hauts salaires tirent la moyenne", "Plus de la moitié des salariés gagne plus de 6 000 MAD", "Les salaires sont répartis de façon égale entre tous", "Le salaire minimum est supérieur à 4 500 MAD"], 'a' => 0, 'e' => "La médiane coupe la population en deux ; une moyenne supérieure à la médiane révèle une queue de hauts salaires. Mnémo : la moyenne est sensible aux extrêmes."],
                    ['q' => "L’écart brut moyen de salaire entre hommes et femmes est de 15 % dans un pays. Cela prouve-t-il une discrimination ?", 'c' => ["Oui, un écart brut est une preuve suffisante", "Pas à lui seul, métiers et heures diffèrent", "Oui, il mesure uniquement la discrimination", "Non, la loi garantit déjà l’égalité"], 'a' => 1, 'e' => "L’écart brut mélange discrimination et différences de postes, d’heures ou d’ancienneté ; il faut comparer à caractéristiques égales pour l’isoler."],
                    ['q' => "Si le nombre de diplômés augmente bien plus vite que la demande de diplômés, la prime salariale du diplôme :", 'c' => ["tend à s’élargir", "devient égale au salaire minimum", "tend à se réduire", "n’est plus mesurable"], 'a' => 2, 'e' => "Plus de diplômés pour une demande inchangée : leur rareté baisse, et avec elle leur prime. C’est la course entre éducation et technologie."],
                    ['q' => "Une entreprise paie ses commerciaux 3 000 MAD fixes plus 5 % du chiffre d’affaires. Quel salaire pour 120 000 MAD de ventes ?", 'c' => ["9 000 MAD", "6 000 MAD", "3 600 MAD", "123 000 MAD"], 'a' => 0, 'e' => "5 % de 120 000 = 6 000 ; 6 000 + 3 000 = 9 000 MAD. Le fixe garantit une base, la commission lie la paie à l’effort."],
                    ['q' => "Que désigne l’expression « plafond de verre » ?", 'c' => ["Un seuil légal de salaire maximal", "Une limite au nombre d’heures travaillées", "Un plafond d’impôt sur les salaires", "Un obstacle invisible à la promotion"], 'a' => 3, 'e' => "Ce sont des freins informels, préjugés ou réseaux fermés, qui bloquent l’accès aux postes élevés pour certains groupes à compétence égale."],
                ],
            ],
            [
                'title' => "Emploi informel et marché du travail",
                'description' => "Définir l’informalité, ses causes, ses conséquences pour les travailleurs et pour les finances publiques.",
                'questions' => [
                    ['q' => "Un emploi informel est un emploi :", 'c' => ["à temps partiel chez un seul et même employeur", "sans déclaration ni protection sociale", "réservé aux travailleurs sans diplôme", "payé uniquement à la commission"], 'a' => 1, 'e' => "L’informalité tient à l’absence de déclaration, de contrat ou de couverture sociale, pas à la durée du travail ni au diplôme."],
                    ['q' => "Un vendeur ambulant sans registre ni couverture sociale exerce :", 'c' => ["un emploi public à temps plein", "un emploi de cadre", "une activité informelle", "un travail intérimaire"], 'a' => 2, 'e' => "Ni enregistrement ni protection sociale : c’est de l’informel. Intérim, emploi public et cadre sont des statuts encadrés."],
                    ['q' => "Quel avantage un salarié déclaré a-t-il sur un salarié non déclaré ?", 'c' => ["Une paie versée en espèces", "Une dispense de contrat écrit", "Des horaires choisis librement par lui", "Couverture maladie et retraite"], 'a' => 3, 'e' => "La déclaration ouvre des droits (maladie, retraite, accidents du travail) financés par les cotisations ; l’informel en est privé."],
                    ['q' => "Pourquoi certaines entreprises choisissent-elles de rester informelles ?", 'c' => ["Pour éviter cotisations et impôts", "Pour accéder facilement au crédit bancaire", "Pour répondre aux appels d’offres publics", "Pour offrir plus de garanties aux salariés"], 'a' => 0, 'e' => "Rester hors du système réduit les coûts immédiats, mais prive de crédit, de marchés publics et de croissance. Mnémo : on économise aujourd’hui, on perd demain."],
                    ['q' => "Sur 10 millions d’actifs occupés, 6 millions n’ont ni contrat ni déclaration. Quel est le taux d’informalité de l’emploi ?", 'c' => ["40 % de l’emploi", "6 % de l’emploi", "60 %", "66 %"], 'a' => 2, 'e' => "6 ÷ 10 = 60 %. Le chiffre de 40 % est la part de l’emploi formel, son complément."],
                    ['q' => "Quelle conséquence de l’informalité pèse sur les finances publiques ?", 'c' => ["Des recettes fiscales plus élevées", "Moins de cotisations collectées", "Une baisse des dépenses de défense", "Un excédent de la balance des paiements"], 'a' => 1, 'e' => "Revenus et salaires non déclarés échappent à l’impôt et aux cotisations, ce qui réduit les ressources de la protection sociale."],
                    ['q' => "Le secteur informel emploie une large part des actifs dans beaucoup de pays en développement, notamment parce que :", 'c' => ["le secteur formel crée trop peu d’emplois", "les salaires y sont supérieurs à ceux du formel", "l’État interdit les contrats écrits", "les entreprises formelles refusent les jeunes"], 'a' => 0, 'e' => "Quand les emplois formels sont rares, beaucoup acceptent des activités informelles pour gagner leur vie. Ce n’est pas toujours un choix, ni mieux rémunéré."],
                    ['q' => "Quelle politique peut aider à réduire l’informalité ?", 'c' => ["Augmenter les cotisations des petites entreprises", "Supprimer les droits sociaux des salariés déclarés", "Fermer les marchés de quartier", "Alléger et simplifier la formalisation"], 'a' => 3, 'e' => "Moins de paperasse et de coûts d’entrée, plus d’avantages (crédit, protection) : la formalisation devient intéressante. Relever les charges ferait l’inverse."],
                    ['q' => "En période de crise économique, comment l’informel se comporte-t-il souvent ?", 'c' => ["Il disparaît faute de clients", "Il sert de refuge aux licenciés", "Il se formalise massivement", "Il devient plus productif que le formel"], 'a' => 1, 'e' => "Faute d’allocation, des licenciés créent de petites activités pour vivre : l’informel amortit le choc, mais avec une faible productivité."],
                    ['q' => "Quel indicateur permet de mesurer l’importance de l’informalité ?", 'c' => ["Le taux d’intérêt directeur de la banque centrale", "Le solde de la balance commerciale du pays", "La part des occupés non affiliés à la sécurité sociale", "L’indice des prix à la consommation des ménages"], 'a' => 2, 'e' => "Compter les emplois sans affiliation sociale ni contrat donne l’ampleur du phénomène. Les autres indicateurs mesurent la monnaie, le commerce extérieur ou les prix."],
                ],
