            [
                'title' => "Applications et raisonnement sur le marché du travail",
                'description' => "Situations concrètes de productivité, d’automatisation, de migration et de politiques de l’emploi.",
                'questions' => [
                    ['q' => "Une usine passe de 100 à 120 ouvriers et de 5 000 à 5 700 pièces par mois. La productivité par ouvrier a :", 'c' => ["baissé, de 50 à 47,5 pièces", "augmenté, car la production a crû de 14 %", "stagné autour de 50 pièces", "augmenté de 20 %"], 'a' => 0, 'e' => "5 000 ÷ 100 = 50 et 5 700 ÷ 120 = 47,5. Produire plus au total ne veut pas dire produire plus par ouvrier : les nouveaux ont apporté moins que la moyenne."],
                    ['q' => "Une boulangerie ajoute un ouvrier à la fois ; la production horaire devient 20, 38, 52 puis 62 pièces. Quelle est la production supplémentaire due au 4e ouvrier ?", 'c' => ["62 pièces", "15,5 pièces", "14 pièces", "10 pièces"], 'a' => 3, 'e' => "62 − 52 = 10 : c’est la productivité marginale du 4e ouvrier, plus faible que celles des précédents (20, 18, 14). On parle de rendements décroissants."],
                    ['q' => "Une machine à 300 000 MAD remplace 3 ouvriers payés 8 000 MAD par mois chacun. Au bout de combien de mois est-elle rentabilisée, en ignorant les autres coûts ?", 'c' => ["environ 37,5 mois", "12,5 mois", "100 mois", "9 mois"], 'a' => 1, 'e' => "Économie mensuelle : 3 × 8 000 = 24 000 MAD ; 300 000 ÷ 24 000 = 12,5 mois. Ne compter qu’un salaire donnerait 37,5."],
                    ['q' => "L’automatisation d’une tâche répétitive dans un entrepôt peut conduire à :", 'c' => ["plus de postes routiniers et moins de postes techniques", "une demande inchangée pour toutes les tâches", "moins de postes routiniers, plus de postes techniques", "une hausse des salaires des tâches remplacées"], 'a' => 2, 'e' => "La machine remplace le travail routinier mais complète le travail technique (réglage, maintenance) : la composition de l’emploi change, pas seulement son volume."],
                    ['q' => "Dans un pays, de nombreux jeunes diplômés sont au chômage alors que des entreprises peinent à recruter. Quelle explication relève d’un décalage ?", 'c' => ["Les jeunes refusent de se former", "Les compétences acquises ne correspondent pas aux postes proposés", "Le salaire minimum interdit d’embaucher des jeunes", "La population active diminue"], 'a' => 1, 'e' => "Si les filières enseignées ne répondent pas aux métiers recherchés, il y a du chômage structurel malgré les diplômes."],
                    ['q' => "Une cimenterie qui employait 800 personnes ferme. Des emplois disparaissent aussi chez ses fournisseurs et dans les commerces voisins. De quoi s’agit-il ?", 'c' => ["D’un effet multiplicateur local négatif", "D’une hausse de la productivité du travail local", "D’un effet de substitution entre capital et travail", "D’un ajustement frictionnel"], 'a' => 0, 'e' => "Quand l’employeur principal disparaît, revenus et dépenses locales baissent, ce qui détruit d’autres emplois : l’effet multiplicateur joue à la baisse."],
                    ['q' => "L’emploi a augmenté de 200 000 postes dans un pays, mais le chômage n’a pas baissé. Quelle explication est cohérente ?", 'c' => ["Le taux d’activité a baissé", "Le salaire minimum a diminué", "La population active a crû autant", "Le nombre de postes vacants a diminué"], 'a' => 2, 'e' => "Si 200 000 personnes de plus entrent sur le marché du travail, le nombre de chômeurs reste identique malgré les créations d’emplois."],
                    ['q' => "Pourquoi, plus un chômage dure, devient-il difficile de retrouver un emploi ?", 'c' => ["Les allocations augmentent avec le temps", "Le salaire minimum baisse peu à peu", "Les entreprises préfèrent recruter des inactifs", "Les compétences s’érodent et les employeurs se méfient"], 'a' => 3, 'e' => "Les compétences se périment et une longue absence est un signal négatif pour l’employeur : le chômage de longue durée tend à s’auto-entretenir."],
                    ['q' => "Un afflux de 5 000 migrants arrive dans le bâtiment d’une ville ; ils sont de proches substituts des ouvriers installés. À court terme, que subit leur salaire ?", 'c' => ["Une pression à la baisse", "Une hausse automatique", "Une fixation par les migrants", "Aucune pression"], 'a' => 0, 'e' => "L’offre de travail du secteur augmente : à demande donnée, le salaire d’équilibre tend à baisser. L’effet dépend aussi de la demande, qui peut croître avec l’arrivée des migrants."],
                    ['q' => "Le PIB d’un pays recule de 3 % par rapport à son potentiel. Que prévoit la loi d’Okun, qualitativement ?", 'c' => ["Une baisse du chômage", "Une absence de lien avec l’emploi", "Une hausse du chômage", "Une baisse de la population active"], 'a' => 2, 'e' => "Quand le PIB recule par rapport à son potentiel, les entreprises produisent moins avec moins de monde : le chômage augmente."],
                    ['q' => "Comment savoir si une hausse du salaire minimum a détruit des emplois dans une ville ?", 'c' => ["Comparer le salaire minimum à la température moyenne", "Demander leur avis à des économistes sans données", "Regarder l’emploi après la mesure sans point de repère", "Comparer avec une ville voisine non concernée"], 'a' => 3, 'e' => "Le groupe témoin neutralise la conjoncture commune : si l’écart d’emploi n’apparaît que dans la ville touchée, la mesure est probablement en cause."],
                ],
            ],
            [
                'title' => "Révision générale de l’économie du travail",
                'description' => "Révision mêlant mesures du marché du travail, mécanismes de salaire, formation, informalité et politiques de l’emploi.",
                'questions' => [
                    ['q' => "Dans un pays, 40 millions de personnes ont l’âge de travailler, 24 millions sont actives et 21,6 millions ont un emploi. Quel est le taux de chômage ?", 'c' => ["6 %", "9 %", "10 %", "environ 54 %"], 'a' => 2, 'e' => "Chômeurs : 24 − 21,6 = 2,4 millions ; 2,4 ÷ 24 = 10 %. Diviser par 40 donnerait 6 %, mais on rapporte aux actifs."],
                    ['q' => "Quel facteur déplace l’offre de travail vers la droite ?", 'c' => ["Une hausse des commandes aux entreprises", "Une hausse de la population en âge de travailler", "Une hausse de la productivité des machines", "Une baisse des prix de vente des produits"], 'a' => 1, 'e' => "Plus de personnes disponibles à chaque salaire : l’offre se déplace à droite. Commandes et productivité agissent sur la demande."],
                    ['q' => "Le salaire d’équilibre et l’emploi d’équilibre augmentent tous deux. Quel déplacement l’explique ?", 'c' => ["Une hausse de l’offre de travail", "Une baisse de la demande de main-d’œuvre", "Une baisse de l’offre de travail", "Une hausse de la demande de travail"], 'a' => 3, 'e' => "La demande se déplace à droite : salaire et emploi montent. Une hausse de l’offre ferait monter l’emploi mais baisser le salaire."],
                    ['q' => "Qu’est-ce qui augmente quand des chômeurs découragés cessent de chercher ?", 'c' => ["Le nombre d’inactifs", "Le taux d’emploi du pays", "Le nombre d’actifs occupés", "Le taux d’activité du pays"], 'a' => 0, 'e' => "Ils quittent la population active pour l’inactivité : le nombre d’inactifs monte et le taux d’activité baisse."],
                    ['q' => "Quelle mesure vise à réduire le chômage structurel ?", 'c' => ["Relever le salaire minimum légal", "Augmenter la durée des allocations", "Financer des formations aux métiers recherchés", "Raccourcir le congé annuel"], 'a' => 2, 'e' => "Le chômage structurel vient d’un décalage de compétences : former les chômeurs aux métiers demandés s’attaque à la cause. Les autres mesures ne rapprochent pas compétences et postes."],
                    ['q' => "Après une hausse de salaire, une personne choisit de moins travailler car elle gagne déjà plus. Quel effet décrit-on ?", 'c' => ["L’effet de revenu", "L’effet de substitution", "L’effet de composition", "L’effet de report"], 'a' => 0, 'e' => "Plus riche, elle s’offre plus de loisirs. L’effet de substitution agit à l’inverse : le loisir coûte plus cher, donc on travaille davantage."],
                    ['q' => "Quelle affirmation sur l’informalité est correcte ?", 'c' => ["Elle se limite aux pays riches", "Elle prive les travailleurs de protection sociale", "Elle augmente les recettes fiscales", "Elle est un signe de plein emploi"], 'a' => 1, 'e' => "Sans déclaration, pas de cotisations, donc pas d’assurance maladie ni de retraite. Le phénomène est plus fréquent dans les pays à revenu faible ou intermédiaire."],
                    ['q' => "Comment appelle-t-on un employeur dominant sur le marché local du travail ?", 'c' => ["Un monopole naturel", "Un oligopole", "Un duopole", "Un monopsone"], 'a' => 3, 'e' => "Le monopsone est l’unique acheteur de travail ; le monopole est l’unique vendeur d’un produit. Mnémo : mono-psone, un seul employeur."],
                    ['q' => "De 2020 à 2024, le salaire nominal d’une employée passe de 4 000 à 4 400 MAD tandis que les prix augmentent de 15 %. Que dire de son pouvoir d’achat ?", 'c' => ["Il a diminué d’environ 4 %", "Il a augmenté de 10 % environ", "Il a augmenté d’environ 5 %", "Il est resté à peu près stable"], 'a' => 0, 'e' => "Salaire +10 % contre prix +15 % : 1,10 ÷ 1,15 ≈ 0,96, soit −4 %. Gagner plus en dirhams ne suffit pas à gagner en pouvoir d’achat."],
                    ['q' => "Quelle mesure cherche à réduire le chômage frictionnel ?", 'c' => ["Une prime à l’investissement des entreprises", "Une plateforme publique qui diffuse les offres d’emploi", "Un relèvement des droits de douane", "Une baisse du taux directeur"], 'a' => 1, 'e' => "Le frictionnel vient du temps de recherche et du manque d’information : mieux diffuser offres et CV raccourcit l’appariement."],
                    ['q' => "Lequel de ces facteurs n’explique pas une différence de salaire entre deux travailleurs ?", 'c' => ["Le niveau de diplôme", "L’expérience sur le poste", "Le prénom du salarié", "Le risque lié au métier"], 'a' => 2, 'e' => "Formation, expérience et pénibilité jouent sur la productivité ou la compensation ; le prénom n’a aucune valeur économique, et un écart lié à lui relèverait de la discrimination."],
                    ['q' => "Quel indicateur mesure la production par heure travaillée ?", 'c' => ["Le salaire horaire minimum", "Le taux d’activité", "Le coût unitaire du capital", "La productivité horaire"], 'a' => 3, 'e' => "Productivité = production ÷ heures travaillées. Si elle progresse durablement, le niveau de vie moyen peut s’élever."],
                ],
            ],
        ];

        foreach ($quizzes as $position => $quizData) {
            $quiz = Quiz::updateOrCreate(
                [
                    'subject_id' => $subject->id,
                    'title' => $quizData['title'],
                ],
                [
                    'owner_id' => null,
                    'description' => $quizData['description'],
                    'duration' => $settings[$position]['duration'],
                    'passing_score' => $settings[$position]['passing_score'],
                    'total_marks' => count($quizData['questions']),
                    'is_active' => true,
                    'difficulty' => 'Beginner',
                ]
            );

            foreach ($quizData['questions'] as $qIndex => $item) {
                $question = Question::updateOrCreate(
                    [
                        'quiz_id' => $quiz->id,
                        'order' => $qIndex + 1,
                    ],
                    [
                        'question' => $item['q'],
                        'type' => 'multiple_choice',
                        'marks' => 1,
                        'explanation' => $item['e'],
                    ]
                );

                foreach ($item['c'] as $cIndex => $text) {
                    Choice::updateOrCreate(
                        [
                            'question_id' => $question->id,
                            'order' => $cIndex + 1,
                        ],
                        [
                            'choice_text' => $text,
                            'is_correct' => $cIndex === $item['a'],
                        ]
                    );
                }

                $question->choices()->where('order', '>', count($item['c']))->delete();
            }
        }
    }
}
